files.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #f0f0f5;
  padding: 16px;
}

.card {
  background: #2a2a3d;
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 380px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: #a78bfa;
  letter-spacing: 0.5px;
}

.display {
  background: #1e1e2f;
  border-radius: 12px;
  padding: 16px;
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 24px;
  min-height: 3.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #3f3f5a;
  color: #e0e0ff;
  word-break: break-word;
}

.display.success {
  border-color: #34d399;
  color: #34d399;
}

.display.error {
  border-color: #f87171;
  color: #f87171;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.key {
  background: #3f3f5a;
  border: none;
  border-radius: 12px;
  padding: 16px 0;
  font-size: 1.25rem;
  font-weight: 600;
  color: #f0f0f5;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: inherit;
}

.key:hover {
  background: #52527a;
}

.key:focus-visible {
  outline: 3px solid #a78bfa;
  outline-offset: 2px;
}

.key:active {
  transform: scale(0.95);
  background: #2a2a3d;
}

.key:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.key#clear {
  background: #7a3f5a;
}

.key#clear:hover {
  background: #9a4f6a;
}

.key#enter {
  background: #3f6a5a;
}

.key#enter:hover {
  background: #4f8a6a;
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  color: #a0a0b8;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .key {
    padding: 14px 0;
    font-size: 1.1rem;
  }
  .display {
    font-size: 1.1rem;
  }
}

(function () {
  'use strict';

  const CODE = '4271';
  const MAX_WRONG = 3;
  const LOCK_SECONDS = 10;

  const display = document.getElementById('display');
  const hint = document.getElementById('hint');
  const keys = Array.from(document.querySelectorAll('.key'));

  let input = '';
  let wrongCount = 0;
  let locked = false;
  let lockTimer = null;
  let countdownTimer = null;

  function updateDisplay(text, state) {
    display.textContent = text;
    display.classList.remove('success', 'error');
    if (state) display.classList.add(state);
  }

  function setKeysDisabled(disabled) {
    keys.forEach(function (btn) {
      btn.disabled = disabled;
    });
  }

  function lockKeypad() {
    locked = true;
    setKeysDisabled(true);
    let remaining = LOCK_SECONDS;
    updateDisplay('Locked: ' + remaining + 's', 'error');
    countdownTimer = setInterval(function () {
      remaining -= 1;
      if (remaining > 0) {
        updateDisplay('Locked: ' + remaining + 's', 'error');
      }
    }, 1000);
    lockTimer = setTimeout(function () {
      clearInterval(countdownTimer);
      locked = false;
      wrongCount = 0;
      setKeysDisabled(false);
      updateDisplay('Enter code', '');
    }, LOCK_SECONDS * 1000);
  }

  function handleDigit(digit) {
    if (locked) return;
    if (input.length < 4) {
      input += digit;
      updateDisplay(input, '');
    }
  }

  function handleClear() {
    if (locked) return;
    input = '';
    updateDisplay('Enter code', '');
  }

  function handleEnter() {
    if (locked) return;
    if (input === CODE) {
      updateDisplay('Unlocked', 'success');
      input = '';
      wrongCount = 0;
    } else {
      wrongCount += 1;
      input = '';
      if (wrongCount >= MAX_WRONG) {
        lockKeypad();
      } else {
        updateDisplay('Wrong code', 'error');
        setTimeout(function () {
          if (!locked) updateDisplay('Enter code', '');
        }, 1500);
      }
    }
  }

  keys.forEach(function (btn) {
    btn.addEventListener('click', function () {
      if (locked) return;
      const digit = btn.getAttribute('data-digit');
      if (digit !== null) {
        handleDigit(digit);
      } else if (btn.id === 'clear') {
        handleClear();
      } else if (btn.id === 'enter') {
        handleEnter();
      }
    });
  });

  document.addEventListener('keydown', function (e) {
    if (locked) return;
    if (e.key >= '0' && e.key <= '9') {
      handleDigit(e.key);
    } else if (e.key === 'Escape') {
      handleClear();
    } else if (e.key === 'Enter') {
      handleEnter();
    }
  });
})();
